/**
 * format-reference.test.js — the Formats reference page is derived from the
 * framework schemas and is current.
 *
 * cli/website/docs/reference/formats.md is generated by
 * cli/scripts/build-format-reference.mjs from
 * shared/schemas/framework/*.v1.schema.json. A schema change without a
 * regenerated page is drift: `--check` exits 3.
 */
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const SCRIPT = path.resolve(__dirname, '..', 'scripts', 'build-format-reference.mjs');
const PAGE = path.resolve(__dirname, '..', 'website', 'docs', 'reference', 'formats.md');
const SCHEMA_DIR = path.resolve(__dirname, '..', 'shared', 'schemas', 'framework');

const { SCHEMA_FILES, build } = await import(SCRIPT);

describe('formats reference (build-format-reference.mjs)', () => {
  it('the committed page is current (--check exits 0)', () => {
    const r = spawnSync(process.execPath, [SCRIPT, '--check'], { encoding: 'utf8' });
    assert.equal(r.status, 0, `formats.md is stale: ${r.stderr}\nRegenerate: node cli/scripts/build-format-reference.mjs`);
  });

  it('covers every framework document schema, each under its own heading with its id', () => {
    const page = fs.readFileSync(PAGE, 'utf8');
    assert.match(page, /^slug: \/reference\/formats$/m);
    assert.match(page, /^title: Formats$/m);
    const onDisk = fs.readdirSync(SCHEMA_DIR).filter((f) => f.endsWith('.v1.schema.json')).sort();
    assert.deepEqual([...SCHEMA_FILES].sort(), onDisk, 'a framework schema is missing from the generator');
    for (const file of SCHEMA_FILES) {
      const schema = JSON.parse(fs.readFileSync(path.join(SCHEMA_DIR, file), 'utf8'));
      const name = schema.$id.match(/\/schemas\/(.+)\/(\d+)\.json$/).slice(1).join('/');
      assert.ok(page.includes(`\n## ${name}\n`), `no section for ${name}`);
      assert.ok(page.includes(`\`${schema.$id}\``), `${name}: its id is not shown`);
      assert.ok(page.includes(`shared/schemas/framework/${file}`), `${file} is not named`);
    }
  });

  it('flattens nested fields and lists every top-level field of every schema', () => {
    const page = build();
    for (const row of ['`pair.source`', '`terms.speakers_agreed`', '`holders_agreed.by`',
      '`evidence[].score`', '`gates[].on_refuse`', '`serve.port`', '`meta.output_local_only`']) {
      assert.ok(page.includes(`| ${row} |`), `missing row ${row}`);
    }
    for (const file of SCHEMA_FILES) {
      const schema = JSON.parse(fs.readFileSync(path.join(SCHEMA_DIR, file), 'utf8'));
      for (const key of Object.keys(schema.properties || {})) {
        assert.ok(page.includes(`| \`${key}\` |`), `${file}: field ${key} has no row`);
      }
    }
  });

  it('--check exits 3 when the committed page differs, and writes nothing', () => {
    // Run a copy of the generator against a temp tree so the real page is untouched.
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'format-ref-'));
    const scripts = path.join(tmp, 'cli', 'scripts');
    const outDir = path.join(tmp, 'cli', 'website', 'docs', 'reference');
    fs.mkdirSync(scripts, { recursive: true });
    fs.mkdirSync(outDir, { recursive: true });
    fs.cpSync(SCHEMA_DIR, path.join(tmp, 'shared', 'schemas', 'framework'), { recursive: true });
    fs.copyFileSync(SCRIPT, path.join(scripts, 'build-format-reference.mjs'));
    const stale = path.join(outDir, 'formats.md');
    fs.writeFileSync(stale, fs.readFileSync(PAGE, 'utf8') + '\nhand edit\n');
    const r = spawnSync(process.execPath, [path.join(scripts, 'build-format-reference.mjs'), '--check'],
      { encoding: 'utf8' });
    assert.equal(r.status, 3, r.stderr);
    assert.match(fs.readFileSync(stale, 'utf8'), /hand edit/);
    fs.rmSync(tmp, { recursive: true, force: true });
  });
});
